import java.io.*;import java.util.InputMismatchException;import java.util.Objects;import java.util.function.IntPredicate;import java.util.function.Predicate;public class MyScan {    private int size = 1024;    char[] buffer = new char[size];    Reader reader;    private boolean passedNewLine = false;    private String token = "";    private boolean closed, readerIsClosed, isLastBuffer;    private boolean emptyLine = false;    private int pointer, length;    private boolean firstOpen = true;    private boolean newLine = true;    private static final String lineSeparator = System.getProperty("line.separator");    private boolean firstLine = true;    private void ensureOpen() {        if (closed)            throw new IllegalStateException("Scanner closed");    }    public void close() {        if (closed)            return;        closed = true;    }    public MyScan(String source) {        pointer = 0;        this.reader = new StringReader(Objects.requireNonNull(source));    }    public MyScan(InputStream source) {        pointer = 0;        firstLine = true;        this.reader = new InputStreamReader(Objects.requireNonNull(source));    }    public MyScan(Reader source) {        pointer = 0;        this.reader = Objects.requireNonNull(source);    }    public MyScan(FileReader source) {        pointer = 0;        this.reader = Objects.requireNonNull(source);    }    private void extendBuffer() {        try {            this.pointer = 0;            if (!readerIsClosed) {                this.length = reader.read(buffer);                if (length < size) {                    isLastBuffer = true;                    reader.close();                    this.readerIsClosed = true;                }            } else {                close();            }            if (firstOpen) {                if (length <= 0) {                    close();                }                firstOpen = false;            }        } catch (IOException e) {            close();        }    }    public boolean hasNextLine() {        if (length <= 0) {            extendBuffer();        }        if (pointer >= length) {            extendBuffer();        }        if (closed){            return false;        }        if (lineSeparator.indexOf(buffer[pointer]) == lineSeparator.length() - 1 && !firstLine) {            pointer++;        } else{            firstLine = false;        }        if (pointer >= length) {            extendBuffer();        }        if (closed){            return false;        }        int p = lineSeparator.indexOf(buffer[pointer]);        int k = 0;        if (p == 0) {            for (int i = 0; i < lineSeparator.length(); i++) {                p = lineSeparator.indexOf(buffer[pointer]);                if (p == k) {                    k++;                }                if (k == lineSeparator.length()) {                    emptyLine = true;                    return true;                }                pointer++;                if (pointer >= length) {                    extendBuffer();                }                if (closed){                    return false;                }            }        }        return hasNext();    }    public static boolean nextFunction(int x) {        return !Character.isWhitespace(x) || (lineSeparator.indexOf(x)!=-1 && Character.isWhitespace(x));    }    public boolean hasNext() {        if (closed) {            return false;        }        int lineCheck;        int k = 0;        if (length <= 0) {            extendBuffer();        }        newLine = false;        while (!isLastBuffer || (pointer < length)) {            if (pointer >= length) {                extendBuffer();            }            if (closed) {                return false;            }            if (!Character.isWhitespace(buffer[pointer]) || newLine || lineSeparator.indexOf(buffer[pointer]) != -1) {                return true;            }            lineCheck = lineSeparator.indexOf(buffer[pointer]);            if (lineCheck != -1) {                if (lineCheck == k) {                    k += 1;                }                if (k == lineSeparator.length()) {                    passedNewLine =true;                    newLine = true;                    pointer++;                    return true;                } else if (k > lineSeparator.length()) {                    k = 1;                }            } else {                k = 0;            }            pointer++;            if (pointer >= length && !isLastBuffer) {                extendBuffer();            }        }        return false;    }    public boolean hasNextInt() {        if (closed) {            return false;        }        if (length <= 0) {            extendBuffer();        }        if (hasNext()) {            token = next();            try {                Integer.parseInt(token);                return true;            } catch (NumberFormatException e) {                return false;            }        } else {            return false;        }    }    private static boolean lineFunction(int x) {        return true;    }    public String nextLine() {        return next(MyScan::lineFunction);    }    public int nextInt() {        try {            if (token.isEmpty()) {                token = next();            }            String res = token;            token = "";            return Integer.parseInt(res);        } catch (NumberFormatException nfe) {            throw new InputMismatchException(nfe.getMessage());        }    }    public String next() {        return next(MyScan::nextFunction);    }    public String next(IntPredicate function) {        if (emptyLine) {            emptyLine = false;            return "";        }        ensureOpen();        if (length <= 0) {            extendBuffer();        }        if (pointer >= length && length == size) {            extendBuffer();        }        newLine = false;        int end, lineCheck;        int k = 0;        StringBuilder res = new StringBuilder();        if (!token.isEmpty()) {            res.append(token);            token = "";        }        while ((!isLastBuffer || (pointer < length)) && !newLine) {            if (function.test(buffer[pointer])) {                end = pointer;                while ((!isLastBuffer || (end < length)) && function.test(buffer[end]) && !newLine) {                    res.append(buffer[end]);                    lineCheck = lineSeparator.indexOf(buffer[end]);                    if (lineCheck != -1) {                        if (lineCheck == k) {                            k += 1;                        }                        if (k == lineSeparator.length()) {                            passedNewLine = true;                            newLine = true;                            pointer = end + 1;                            return res.substring(0, res.length() - k);                        } else if (k > lineSeparator.length()) {                            k = 1;                        }                    } else {                        k = 0;                    }                    end++;                    if (end >= length && !isLastBuffer) {                        extendBuffer();                        end = 0;                    }                }                if (newLine) {                    k = lineSeparator.length() - 1;                } else {                    k = 0;                }                pointer = end;                return res.substring(0, res.length() - k);            }            lineCheck = lineSeparator.indexOf(buffer[pointer]);            if (lineCheck != -1) {                if (lineCheck == k) {                    k++;                }                if (k == lineSeparator.length()) {                    passedNewLine = true;                    newLine = true;                    k = 0;                } else if (k > lineSeparator.length()) {                    k = 1;                }            } else {                k = 0;            }            pointer++;            if (pointer >= length && !isLastBuffer) {                extendBuffer();            }        }        return res.toString();    }    public boolean isPassedNewLine() {        boolean res = passedNewLine;        passedNewLine = false;        return res;    }}